contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address account, uint256 tokenId, uint256 amount) public payable {
        // caller (this contract) has not been set as an allowed burning address
        uint256 balBefore = c.balanceOf(account, tokenId);
        bool reverted1;
        try c.burn(account, tokenId, amount) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        // grant ourselves burning rights (we are admin, we deployed c)
        c.setAllowedBurningAddresses(address(this));
        uint256 balMid = c.balanceOf(account, tokenId);
        bool reverted2;
        // balance is zero and cannot be increased without minting via the Neuron flow,
        // so burning more than the balance must revert
        try c.burn(account, tokenId, amount) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        assert(
            reverted1 == true &&
            reverted2 == (amount > balMid) &&
            c.balanceOf(account, tokenId) == balBefore &&
            (reverted1 || c.balanceOf(account, tokenId) + amount <= type(uint256).max)
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address operator, address otherOperator, bool approved) public payable {
        require(operator != address(this), "operator cannot be caller");
        require(otherOperator != operator, "operators must differ");
        bool beforeOther = c.isApprovedForAll(address(this), otherOperator);
        c.setApprovalForAll(operator, approved);
        bool afterSelf = c.isApprovedForAll(address(this), operator);
        bool afterOther = c.isApprovedForAll(address(this), otherOperator);
        assert(afterSelf == approved && afterOther == beforeOther);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory accounts, uint256[] memory ids) public payable {
        require(accounts.length == ids.length, "length mismatch");
        for (uint256 i = 0; i < accounts.length; i++) {
            require(accounts[i] != address(0), "zero account");
        }
        bool reverted;
        uint256[] memory batch;
        try c.balanceOfBatch(accounts, ids) returns (uint256[] memory r) {
            reverted = false;
            batch = r;
        } catch {
            reverted = true;
        }
        assert(!reverted && batch.length == accounts.length);
    }
    receive() external payable {}
}

