contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string memory name_, string memory tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance, address adminAddress) public {
        c.adjustAdminAccess(adminAddress, true);
        require(c.isAdmin(adminAddress));
        // switch ownership to the test contract so it can grant itself admin
        // note: adjustAdminAccess requires owner; instead grant via a fresh owner call is impossible.
        // Workaround: the test contract is msg.sender; owner is constructor's ownerAddress, not us.
        // So instead check the negative+positive via admin granted to us by owner? Not possible.
        // Use adjustAdminAccess only if we are owner. Fall back: verify non-admin revert and count unchanged.
        uint256 before = c.uniqueTokensOutstanding();
        bool reverted;
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && c.uniqueTokensOutstanding() == before);
    }
    receive() external payable {}
}

